from lc import L, w, gr, q

B2 = [
 L("How Much Water Do We Really Need?", "我們到底需要喝多少水？", [
   "Water makes up around 60 percent of an adult's body, and we lose some of it every day through breathing, sweating and going to the toilet. Replacing that water is essential for controlling body temperature and keeping our organs working properly.",
   "You may have heard that everyone should drink eight glasses a day, but this rule is not based on strong scientific evidence. How much you need depends on your size, how active you are and the climate you live in. A surprising amount also comes from food, especially fruit and vegetables.",
   "Early signs of dehydration include thirst, headaches and dark yellow urine. For many people around the world, the bigger problem is access: roughly two billion people still do not have a reliable supply of safe drinking water at home."],
  [w("essential","adjective","/ɪˈsen.ʃəl/","不可或缺的","completely necessary","Water is essential for life.","be essential for + 名詞／V-ing。"),
   w("organ","noun","/ˈɔːr.ɡən/","器官","a part of the body with a special job, such as the heart","The heart is an organ.","複數 organs。"),
   w("evidence","noun","/ˈev.ə.dəns/","證據","facts that show something is true","There is no evidence for this.","不可數名詞；scientific evidence。"),
   w("climate","noun","/ˈklaɪ.mət/","氣候","the usual weather in a place","a hot climate","the climate you live in 你住的地方的氣候。"),
   w("dehydration","noun","/ˌdiː.haɪˈdreɪ.ʃən/","脫水","a harmful lack of water in the body","Dehydration causes headaches.","de- + hydration。"),
   w("thirst","noun","/θɝːst/","口渴","the feeling of needing to drink","I have a terrible thirst.","形容詞 thirsty。"),
   w("access","noun","/ˈæk.ses/","取得的機會","the right or chance to use something","access to clean water","access to + 名詞。")],
  [gr("make up","構成、占（比例）。","Water makes up around 60 percent of an adult's body"),
   gr("depend on + 名詞子句","取決於…（後接 how/what 子句）。","How much you need depends on your size"),
   gr("名詞子句當主詞","How much you need 整句當主詞。","How much you need depends on your size, how active you are and the climate you live in.")],
  [q("Why does the body need to replace water?","To control temperature and keep organs working","To make us taller","To stop us breathing"),
   q("What does the text say about 'eight glasses a day'?","It is not based on strong evidence","It is the law","It is too little for everyone"),
   q("What is the bigger problem for many people worldwide?","Access to safe drinking water","Drinking too much water","Too many fruit"),]),
 L("Why More Cities Are Choosing Bikes", "為什麼越來越多城市選擇自行車", [
   "In cities such as Amsterdam and Copenhagen, the bicycle is not just a hobby but a normal way to get to work, school and the shops. Cycling for everyday trips like these is known as utility cycling, and more cities are trying to encourage it.",
   "The benefits are easy to see. Bikes take up little space, produce no exhaust fumes and give riders regular exercise. For short journeys in busy areas, they are often quicker than cars stuck in traffic.",
   "However, people will only switch to cycling if they feel safe. That is why successful cities invest in protected bike lanes, secure parking and public bike-sharing systems like Taiwan's YouBike. Electric bikes are also making longer or hillier trips possible for many riders."],
  [w("hobby","noun","/ˈhɑː.bi/","嗜好","an activity you do for fun in your free time","My hobby is painting.","not just a hobby but… 不只是嗜好而是…。"),
   w("encourage","verb","/ɪnˈkɝː.ɪdʒ/","鼓勵","to make someone more likely to do something","Parents encourage children to read.","encourage + 名詞／人 to V。"),
   w("exhaust","noun","/ɪɡˈzɑːst/","廢氣","waste gas from an engine","car exhaust","exhaust fumes 排放的廢氣。"),
   w("journey","noun","/ˈdʒɝː.ni/","旅程、路程","a trip from one place to another","a short journey","short journeys 短程移動。"),
   w("switch","verb","/swɪtʃ/","轉換","to change from one thing to another","She switched to tea.","switch to + 名詞。"),
   w("invest","verb","/ɪnˈvest/","投資","to spend money to improve something","The city invests in schools.","invest in + 名詞。"),
   w("protected","adjective","/prəˈtek.tɪd/","受保護的","kept safe from harm","protected bike lanes","protected 有實體分隔的。")],
  [gr("not just A but B","不只是 A，而是 B。","the bicycle is not just a hobby but a normal way to get to work"),
   gr("be known as","被稱為…。","Cycling for everyday trips like these is known as utility cycling"),
   gr("only… if…","只有在…的時候才…。","people will only switch to cycling if they feel safe")],
  [q("What is utility cycling?","Cycling for everyday trips","Racing bikes","Fixing bikes"),
   q("Which benefit of bikes is mentioned?","They produce no exhaust fumes","They are faster on highways","They carry many passengers"),
   q("What do people need before they switch to cycling?","To feel safe","Expensive bikes","Long holidays")]),
 L("Why Night Markets Are So Special", "夜市為什麼這麼特別", [
   "When the sun goes down in Taiwan, quiet streets often turn into busy night markets. Famous ones such as Shilin and Raohe in Taipei attract both locals and tourists, who come to eat, shop and play games under bright lights.",
   "Food is the main attraction. Visitors can wander from stall to stall, trying small portions of stinky tofu, oyster omelets, grilled squid and bubble tea. Because prices are low, it is easy to sample many different dishes in one evening.",
   "Night markets are also an important part of social life. Families stroll together after dinner, friends meet up after work, and small vendors earn a living. Similar evening markets can be found across Asia, but many travelers say Taiwan's are among the liveliest."],
  [w("attract","verb","/əˈtrækt/","吸引","to make people want to come","The beach attracts tourists.","attract + 人。"),
   w("attraction","noun","/əˈtræk.ʃən/","吸引人的事物","something that makes people want to go somewhere","a tourist attraction","the main attraction 最大賣點。"),
   w("wander","verb","/ˈwɑːn.dɚ/","閒逛","to walk around slowly without a clear purpose","We wandered around the town.","wander from A to B。"),
   w("portion","noun","/ˈpɔːr.ʃən/","一份（食物）","an amount of food for one person","a small portion of rice","small portions 小份量。"),
   w("sample","verb","/ˈsæm.pəl/","品嚐、試吃","to try a little of something","Sample the local food.","sample many dishes 吃多種小吃。"),
   w("stroll","verb","/stroʊl/","散步","to walk slowly and relaxedly","We strolled along the river.","stroll together 一起散步。"),
   w("vendor","noun","/ˈven.dɚ/","小販","a person who sells things, often in the street","a street vendor","small vendors 小攤販。")],
  [gr("turn into","變成…。","quiet streets often turn into busy night markets"),
   gr("非限定關係子句 who","補充說明 locals and tourists。","attract both locals and tourists, who come to eat, shop and play games"),
   gr("be among the + 最高級","是最…之一。","many travelers say Taiwan's are among the liveliest")],
  [q("What is the main attraction of night markets?","Food","Museums","Hotels"),
   q("Why is it easy to try many dishes?","Prices are low","Food is free","The markets are open all day"),
   q("Who earns a living at night markets?","Small vendors","Bank workers","Teachers")]),
 L("Can You Tell If a Photo Is Fake?", "你分得出照片是假的嗎？", [
   "AI tools can now create realistic photos of events that never happened. In his TED talk, Hany Farid, a professor who has spent decades studying digital images, explains how experts try to tell real pictures from fake ones.",
   "Some clues are hidden in the physics of the scene. In a real photo, shadows and parallel lines follow consistent rules, while AI-generated images often get these details slightly wrong. Experts also study tiny patterns of noise in the image that ordinary viewers cannot see.",
   "Farid warns that most of us cannot reliably spot fakes with our own eyes. His advice is to slow down before sharing something shocking, check where it came from and rely on trustworthy sources. Avoiding becoming part of the problem, he suggests, is something everyone can do."],
  [w("realistic","adjective","/ˌriː.əˈlɪs.tɪk/","逼真的","looking like the real thing","a realistic painting","real + -istic。"),
   w("decade","noun","/ˈdek.eɪd/","十年","a period of ten years","for two decades","spent decades 花了幾十年。"),
   w("clue","noun","/kluː/","線索","a sign that helps you find an answer","The police found a clue.","clues are hidden in… 線索藏在…。"),
   w("consistent","adjective","/kənˈsɪs.tənt/","一致的","always following the same pattern","consistent results","follow consistent rules 遵循一致的規則。"),
   w("reliably","adverb","/rɪˈlaɪ.ə.bli/","可靠地","in a way that can be trusted","The machine works reliably.","reliable + -ly。"),
   w("shocking","adjective","/ˈʃɑː.kɪŋ/","令人震驚的","very surprising and upsetting","shocking news","something shocking 形容詞放在 something 後。"),
   w("trustworthy","adjective","/ˈtrʌstˌwɝː.ði/","值得信賴的","able to be trusted","a trustworthy friend","trust + worthy。")],
  [gr("tell A from B","分辨 A 和 B。","how experts try to tell real pictures from fake ones"),
   gr("ones 代替名詞","ones = pictures，避免重複。","tell real pictures from fake ones"),
   gr("動名詞片語當主詞","Avoiding becoming… 當主詞。","Avoiding becoming part of the problem, he suggests, is something everyone can do.")],
  [q("What is Hany Farid's area of expertise?","Studying digital images","Making movies","Teaching photography"),
   q("Which clue can show an image is fake?","Shadows that do not follow consistent rules","Bright colors","A famous person in it"),
   q("What does Farid advise before sharing shocking images?","Slow down and check the source","Share quickly","Add a filter")]),
]

C1 = [
 L("Beyond Eight Glasses a Day", "不只是一天八杯水", [
   "Water accounts for roughly 60 percent of an adult's body weight, and it is in constant circulation: we shed it with every breath, every bead of sweat and every trip to the bathroom. Keeping that balance steady is fundamental to regulating temperature, transporting nutrients and allowing the kidneys to clear waste.",
   "Popular advice tends to boil down to a tidy formula: eight glasses a day. The figure is easy to remember but has surprisingly little evidence behind it. Actual requirements fluctuate with body size, activity and climate, and a substantial share of our intake arrives through food.",
   "For healthy people, thirst is generally a dependable guide, although older adults may not feel it as keenly. Mild dehydration tends to announce itself through headaches, fatigue and darker urine long before it becomes dangerous.",
   "Globally, however, the more pressing issue is not how much people drink but whether what they drink is safe. Around two billion people still lack safely managed drinking water, which leaves them exposed to preventable diseases and makes clean water as much a question of justice as of health."],
  [w("shed","verb","/ʃed/","失去、排出","to lose something naturally","Trees shed their leaves.","shed 三態同形。"),
   w("fundamental","adjective","/ˌfʌn.dəˈmen.t̬əl/","根本的","forming the basic part of something","a fundamental right","be fundamental to + 名詞／V-ing。"),
   w("boil down to","phrasal verb","/bɔɪl daʊn tuː/","歸結為","to reduce something to its main point","It boils down to money.","boil down to… 歸結成…。"),
   w("fluctuate","verb","/ˈflʌk.tʃu.eɪt/","波動","to change often in level or amount","Prices fluctuate daily.","fluctuate with… 隨…變動。"),
   w("substantial","adjective","/səbˈstæn.ʃəl/","大量的","large in amount","a substantial increase","a substantial share 相當大的部分。"),
   w("dependable","adjective","/dɪˈpen.də.bəl/","可靠的","able to be trusted","a dependable car","depend + -able。"),
   w("keenly","adverb","/ˈkiːn.li/","強烈地、敏銳地","strongly or sharply","She felt the loss keenly.","feel it keenly 感受強烈。"),
   w("pressing","adjective","/ˈpres.ɪŋ/","緊迫的","needing to be dealt with now","a pressing problem","the more pressing issue 更急迫的問題。")],
  [gr("not A but B","不是 A 而是 B（比較兩個重點）。","the more pressing issue is not how much people drink but whether what they drink is safe"),
   gr("long before","早在…之前很久。","long before it becomes dangerous"),
   gr("as much A as B","A 和 B 程度相當。","as much a question of justice as of health")],
  [q("What does the writer imply about 'eight glasses a day'?","It is memorable but poorly supported","It is the only safe amount","It is too high for everyone"),
   q("Why might older adults need extra care?","They may not feel thirst as strongly","They need no water","They drink too much"),
   q("How does the writer frame the global water problem?","As a matter of justice as well as health","As a fashion trend","As a problem only for athletes")]),
 L("The Quiet Revolution of Utility Cycling", "日常騎車的寧靜革命", [
   "In Amsterdam or Copenhagen, it is unremarkable to see office workers in suits, parents with children perched on cargo bikes and pensioners laden with shopping, all pedaling through rush hour. This is utility cycling: the bike treated as transport rather than sport.",
   "Its appeal to city planners is easy to grasp. Bicycles occupy a fraction of the road space of cars, emit nothing at the tailpipe and build physical activity into daily routines. Over short distances in congested centers, they frequently beat motor traffic door to door.",
   "Yet these cities did not stumble into cycling by accident; they engineered it. Decades of investment produced networks of protected lanes, secure parking and traffic-calmed streets that make riding feel safe even for nervous beginners.",
   "That lesson travels. Surveys consistently show that perceived danger, not distance, is what keeps would-be cyclists off their bikes. Public bike-sharing schemes such as Taiwan's YouBike lower the barrier further, while electric bikes are rapidly widening the range of journeys that cycling can realistically replace."],
  [w("unremarkable","adjective","/ˌʌn.rɪˈmɑːr.kə.bəl/","平常的","ordinary; not unusual","an unremarkable day","it is unremarkable to… …很平常。"),
   w("laden","adjective","/ˈleɪ.dən/","滿載的","carrying a lot of something","laden with bags","be laden with… 載滿…。"),
   w("grasp","verb","/ɡræsp/","理解","to understand something","I couldn't grasp the idea.","easy to grasp 容易理解。"),
   w("congested","adjective","/kənˈdʒes.tɪd/","擁擠的","too full of traffic or people","congested roads","名詞 congestion。"),
   w("stumble","verb","/ˈstʌm.bəl/","偶然碰上","to find or start something by chance","We stumbled into a café.","stumble into… 誤打誤撞進入…。"),
   w("engineer","verb","/ˌen.dʒɪˈnɪr/","精心策劃","to arrange something cleverly","They engineered a deal.","當動詞：刻意設計出來。"),
   w("perceived","adjective","/pɚˈsiːvd/","感覺上的","believed to exist, though maybe not real","perceived risk","perceived danger 主觀認為的危險。"),
   w("would-be","adjective","/ˈwʊd.biː/","想要成為…的","hoping to become","would-be actors","would-be cyclists 想騎車的人。")],
  [gr("rather than","而不是。","the bike treated as transport rather than sport"),
   gr("分號表因果對比","分號後補充真正的原因。","Yet these cities did not stumble into cycling by accident; they engineered it."),
   gr("強調句 is what…","perceived danger 是阻止人們的原因。","perceived danger, not distance, is what keeps would-be cyclists off their bikes")],
  [q("What does the writer mean by 'they engineered it'?","The cities deliberately built conditions for cycling","Engineers invented the bicycle","Cycling happened by chance"),
   q("According to surveys, what mainly stops people from cycling?","Feeling it is dangerous","The distance","The price of bikes"),
   q("What effect are electric bikes having?","Making more kinds of trips possible by bike","Making cycling more dangerous","Replacing bike-sharing")]),
 L("After Dark: The Enduring Appeal of Night Markets", "入夜後：夜市歷久不衰的魅力", [
   "As dusk falls across Taiwan, ordinary streets undergo a nightly transformation. Shuttered storefronts give way to rows of stalls, and by the time the lights flicker on, places like Shilin and Raohe in Taipei are thronged with locals and visitors alike.",
   "The chief draw is, unmistakably, the food. Night markets reward a grazing approach: a skewer of grilled squid here, an oyster omelet there, perhaps a bowl of pungent stinky tofu for the adventurous. Modest prices encourage experimentation in a way that a formal restaurant rarely does.",
   "Yet reducing night markets to a culinary experience would miss much of their significance. They function as open-air living rooms, where families linger after dinner and friends gather without the expense of a café.",
   "For the vendors, often small family businesses, the markets offer a livelihood with low start-up costs. Evening markets exist throughout Asia, but Taiwan's have acquired a particular reputation, and for many visitors an evening spent wandering one has become an essential part of the trip."],
  [w("dusk","noun","/dʌsk/","黃昏","the time just before night","We arrived at dusk.","As dusk falls 夜幕降臨時。"),
   w("transformation","noun","/ˌtræns.fɚˈmeɪ.ʃən/","轉變","a complete change","a dramatic transformation","undergo a transformation 經歷轉變。"),
   w("thronged","adjective","/θrɑːŋd/","擠滿人的","crowded with people","streets thronged with fans","be thronged with… 擠滿…。"),
   w("unmistakably","adverb","/ˌʌn.mɪˈsteɪ.kə.bli/","無疑地","in a way that cannot be confused","unmistakably French","強調語氣。"),
   w("pungent","adjective","/ˈpʌn.dʒənt/","氣味刺鼻的","having a strong smell or taste","pungent cheese","pungent stinky tofu 味道濃烈的臭豆腐。"),
   w("culinary","adjective","/ˈkʌl.ə.ner.i/","烹飪的、飲食的","connected with cooking or food","culinary skills","a culinary experience 美食體驗。"),
   w("linger","verb","/ˈlɪŋ.ɡɚ/","逗留","to stay somewhere longer than necessary","We lingered over coffee.","linger after dinner 飯後逗留。"),
   w("livelihood","noun","/ˈlaɪv.li.hʊd/","生計","the way someone earns money to live","Fishing is their livelihood.","offer a livelihood 提供生計。")],
  [gr("give way to","被…取代。","Shuttered storefronts give way to rows of stalls"),
   gr("by the time","到…的時候（已經）。","by the time the lights flicker on, places like Shilin and Raohe in Taipei are thronged"),
   gr("動名詞當主詞 + would","假設語氣：若把…簡化就會…。","Yet reducing night markets to a culinary experience would miss much of their significance.")],
  [q("What does 'a grazing approach' mean here?","Eating small amounts from many stalls","Eating only vegetables","Eating one big meal"),
   q("Why does the writer call night markets 'open-air living rooms'?","People relax and socialize there","They sell furniture","They are inside houses"),
   q("What advantage do markets give vendors?","A livelihood with low start-up costs","Free rent forever","Government salaries")]),
 L("Seeing Is No Longer Believing", "眼見不再為憑", [
   "Generative AI has made it trivial to produce photographs of events that never took place, and the consequences reach from personal reputations to public trust. Hany Farid, a professor who has spent his career in digital forensics, uses his TED talk to show how specialists fight back.",
   "Much of the evidence lies in physics that image generators only imitate. In a genuine photograph, parallel lines converge on a consistent vanishing point and shadows align with a single light source. Synthetic images frequently break these rules in ways that become obvious once measured.",
   "Other tests probe what the eye cannot see at all, such as the statistical fingerprint of sensor noise that a camera leaves behind. Farid is candid, though, that ordinary viewers cannot rely on intuition, and that detection is an arms race rather than a solved problem.",
   "His prescription therefore focuses on behavior as much as technology. Pause before amplifying sensational images, seek out the original source and favor reputable outlets. If we cannot always spot a fake, he suggests, we can at least decline to spread one."],
  [w("trivial","adjective","/ˈtrɪv.i.əl/","輕而易舉的","very easy; not important","a trivial task","make it trivial to… 讓…變得極容易。"),
   w("forensics","noun","/fəˈren.zɪks/","鑑識學","scientific methods used to examine evidence","digital forensics","digital forensics 數位鑑識。"),
   w("converge","verb","/kənˈvɝːdʒ/","匯聚","to move towards the same point","The roads converge here.","converge on… 匯聚於…。"),
   w("synthetic","adjective","/sɪnˈθet̬.ɪk/","合成的、人造的","made artificially","synthetic fabrics","synthetic images 合成影像。"),
   w("probe","verb","/proʊb/","探查","to examine something closely","Scientists probe the data.","probe what… 探查…。"),
   w("candid","adjective","/ˈkæn.dɪd/","坦白的","honest and direct","a candid answer","be candid that… 坦白承認…。"),
   w("amplify","verb","/ˈæm.plə.faɪ/","放大、擴散","to make something stronger or reach more people","Social media amplifies rumors.","amplifying 動名詞接在 before 後。"),
   w("reputable","adjective","/ˈrep.jə.t̬ə.bəl/","有信譽的","known to be good and honest","a reputable company","reputable outlets 可信的媒體。")],
  [gr("reach from A to B","影響範圍從 A 到 B。","the consequences reach from personal reputations to public trust"),
   gr("rather than","而不是。","detection is an arms race rather than a solved problem"),
   gr("If… can't…, can at least…","即使不能…，至少能…。","If we cannot always spot a fake, he suggests, we can at least decline to spread one.")],
  [q("What physical clue can reveal a synthetic image?","Lines that do not meet at a consistent vanishing point","Too many colors","A missing date"),
   q("What does Farid admit about detection?","It is an ongoing arms race","It is completely solved","Anyone can do it by eye"),
   q("What is the main message of his final advice?","We can choose not to spread fakes","We should stop using cameras","AI should be banned")]),
]
